def sliding_window(input_string: str) -> int:
    if not isinstance(input_string, str):
        raise TypeError('Input must be a string')
    if len(input_string) == 0:
        return 0
    char_index_map: dict[str, int] = {}
    left: int = 0
    max_len: int = 0
    for (right, char) in enumerate(input_string):
        if char in char_index_map and char_index_map[char] >= left:
            left = char_index_map[char] + 1
        char_index_map[char] = right
        current_len = right - left + 1
        max_len = max(max_len, current_len)
    return max_len

def is_palindrome_dict(head: object | None) -> bool:
    if not head or not head.next:
        return True
    positions: dict[object, list[int]] = {}
    pos = 0
    current = head
    while current:
        if current.val in positions:
            positions[current.val].append(pos)
        else:
            positions[current.val] = [pos]
        current = current.next
        pos += 1
    checksum = pos - 1
    middle = 0
    for indices in positions.values():
        if len(indices) % 2 != 0:
            middle += 1
        else:
            for (step, i) in enumerate(range(len(indices))):
                if indices[i] + indices[len(indices) - 1 - step] != checksum:
                    return False
        if middle > 1:
            return False
    return True

def three_sum(array: list[int]) -> set[tuple[int, int, int]]:
    result = set()
    array.sort()
    for i in range(len(array) - 2):
        if i > 0 and array[i] == array[i - 1]:
            continue
        (left, right) = (i + 1, len(array) - 1)
        while left < right:
            current_sum = array[i] + array[left] + array[right]
            if current_sum > 0:
                right -= 1
            elif current_sum < 0:
                left += 1
            else:
                result.add((array[i], array[left], array[right]))
                while left < right and array[left] == array[left + 1]:
                    left += 1
                while left < right and array[right] == array[right - 1]:
                    right -= 1
                left += 1
                right -= 1
    return result

def minkowski_distance(point_a: list[float], point_b: list[float], order: int) -> float:
    if order < 1:
        raise ValueError('The order must be greater than or equal to 1.')
    if len(point_a) != len(point_b):
        raise ValueError('Both points must have the same dimension.')
    return sum((abs(a - b) ** order for (a, b) in zip(point_a, point_b))) ** (1 / order)

def next_bigger(num: int) -> int:
    digits = [int(i) for i in str(num)]
    idx = len(digits) - 1
    while idx >= 1 and digits[idx - 1] >= digits[idx]:
        idx -= 1
    if idx == 0:
        return -1
    pivot = digits[idx - 1]
    swap_idx = len(digits) - 1
    while pivot >= digits[swap_idx]:
        swap_idx -= 1
    (digits[swap_idx], digits[idx - 1]) = (digits[idx - 1], digits[swap_idx])
    digits[idx:] = digits[:idx - 1:-1]
    return int(''.join((str(x) for x in digits)))

def postfix_to_infix(postfix_expression: str) -> str:
    if postfix_expression is None or postfix_expression == '':
        raise ValueError('Invalid postfix expression.')
    stack = []
    for item in postfix_expression:
        if item not in ['+', '-', '*', '/', '^']:
            stack.append(item)
        else:
            operand_2 = stack.pop()
            operand_1 = stack.pop()
            infix_expression = '(' + operand_1 + item + operand_2 + ')'
            stack.append(infix_expression)
    return stack.pop()

def get_exclude_keywords(num_pos_only, sigspec):
    if num_pos_only == 0:
        return ()
    has_kwargs = any((x.kind == x.VAR_KEYWORD for x in sigspec.parameters.values()))
    if not has_kwargs:
        return ()
    pos_args = list(sigspec.parameters.values())[:num_pos_only]
    return tuple((x.name for x in pos_args))

def maximum_non_adjacent_sum(nums: list[int]) -> int:
    if not nums:
        return 0
    max_including = nums[0]
    max_excluding = 0
    for num in nums[1:]:
        (max_including, max_excluding) = (max_excluding + num, max(max_including, max_excluding))
    return max(max_excluding, max_including)

def merge(ids: list[int], pair: tuple, idx: int) -> list[int]:
    new_ids = []
    i = 0
    while i < len(ids):
        if i < len(ids) - 1 and (ids[i] == pair[0] and ids[i + 1] == pair[1]):
            new_ids.append(idx)
            i += 2
        else:
            new_ids.append(ids[i])
            i += 1
    return new_ids

def ceil_index(v, left, right, key):
    while right - left > 1:
        middle = (left + right) // 2
        if v[middle] >= key:
            right = middle
        else:
            left = middle
    return right

def longest_non_repeat_v1(string: str) -> int:
    if string is None:
        return 0
    char_index = {}
    max_length = 0
    start = 0
    for index in range(len(string)):
        if string[index] in char_index:
            start = max(char_index[string[index]], start)
        char_index[string[index]] = index + 1
        max_length = max(max_length, index - start + 1)
    return max_length

def dp_count(s, n):
    if n < 0:
        return 0
    table = [0] * (n + 1)
    table[0] = 1
    for coin_val in s:
        for j in range(coin_val, n + 1):
            table[j] += table[j - coin_val]
    return table[n]

def wiggle_sort(array: list[int]) -> list[int]:
    for i in range(len(array)):
        if (i % 2 == 1) == (array[i - 1] > array[i]):
            (array[i - 1], array[i]) = (array[i], array[i - 1])
    return array

def extended_euclid(a: int, b: int) -> tuple[int, int]:
    if b == 0:
        return (1, 0)
    (x, y) = extended_euclid(b, a % b)
    k = a // b
    return (y, x - k * y)

def all_construct(target: str, word_bank: list[str] | None=None) -> list[list[str]]:
    word_bank = word_bank or []
    table_size: int = len(target) + 1
    table: list[list[list[str]]] = []
    for _ in range(table_size):
        table.append([])
    table[0] = [[]]
    for i in range(table_size):
        if table[i] != []:
            for word in word_bank:
                if target[i:i + len(word)] == word:
                    new_combinations: list[list[str]] = [[word, *way] for way in table[i]]
                    table[i + len(word)] += new_combinations
    for combination in table[len(target)]:
        combination.reverse()
    return table[len(target)]

def insertion_sort(array: list[int]) -> list[int]:
    for i in range(len(array)):
        cursor = array[i]
        pos = i
        while pos > 0 and array[pos - 1] > cursor:
            array[pos] = array[pos - 1]
            pos -= 1
        array[pos] = cursor
    return array

def count(coins: list[int], value: int) -> int:
    dp_array = [1] + [0] * value
    for coin in coins:
        for i in range(coin, value + 1):
            dp_array[i] += dp_array[i - coin]
    return dp_array[value]

def padovan_sequence(n: int) -> int:
    if not isinstance(n, int) or n < 0:
        raise ValueError('Input must be a non-negative integer.')
    if n <= 2:
        return 1
    (p_prev_3, p_prev_2, p_prev_1) = (1, 1, 1)
    for _ in range(3, n + 1):
        curr = p_prev_2 + p_prev_3
        (p_prev_3, p_prev_2, p_prev_1) = (p_prev_2, p_prev_1, curr)
    return p_prev_1
